import pty, os, subprocess, select, fcntl, termios, struct
exec(open("/tmp/compact.py").read())
def run_mix(args, stdin_tty=False, stdout_tty=False, stderr_tty=False):
    masters=[]
    def make():
        m,s=pty.openpty(); fcntl.ioctl(s,termios.TIOCSWINSZ,struct.pack("HHHH",24,80,0,0)); masters.append(m); return s,m
    stdin=subprocess.PIPE; stdout=subprocess.PIPE; stderr=subprocess.PIPE
    ms={}
    if stdin_tty: s,m=make(); stdin=s; ms['in']=m
    if stdout_tty: s,m=make(); stdout=s; ms['out']=m
    if stderr_tty: s,m=make(); stderr=s; ms['err']=m
    env=dict(os.environ); env["DSTASK_GIT_REPO"]=REPO; env["EDITOR"]="/tmp/editor_noop.sh"
    p=subprocess.Popen(["./executable"]+args,stdin=stdin,stdout=stdout,stderr=stderr,env=env)
    for fd in [stdin,stdout,stderr]:
        if fd not in (subprocess.PIPE,): 
            try: os.close(fd)
            except: pass
    outs={}
    for k,m in ms.items():
        if k=='in': continue
        data=b""
        while True:
            r,_,_=select.select([m],[],[],0.5)
            if not r: break
            try: d=os.read(m,65536)
            except: break
            if not d: break
            data+=d
        outs[k]=data
    if not stdout_tty or not stderr_tty:
        try:
            o,e=p.communicate(timeout=2)
        except Exception as ex:
            p.kill(); o=b""; e=str(ex).encode()
        if not stdout_tty: outs['out']=o
        if not stderr_tty: outs['err']=e
    else:
        p.wait(timeout=2)
    print(args,"stdinT",stdin_tty,"stdoutT",stdout_tty,"stderrT",stderr_tty,"rc",p.returncode,"out",outs.get('out'),"err",outs.get('err'))
    print(" notes:", show()[0]["notes"] if show() else None)
