import subprocess,os,shutil
def run(repo,args=["show-open"]):
    env=dict(os.environ); env["DSTASK_GIT_REPO"]=repo; p=subprocess.run(["./executable"]+args,capture_output=True,text=True,env=env); print(args,p.returncode,repr(p.stdout),repr(p.stderr))
def seed():
    repo="/tmp/stateerr"; shutil.rmtree(repo,ignore_errors=True); os.makedirs(repo); subprocess.run(["git","init",repo],capture_output=True); os.makedirs(repo+"/.git/dstask",exist_ok=True); return repo
for kind in ["state-dir","ids-dir","state-empty","ids-empty","state-garbage","ids-garbage","state-random","ids-wrongtype"]:
    repo=seed()
    if kind=="state-dir": os.makedirs(repo+"/.git/dstask/state.bin")
    if kind=="ids-dir": os.makedirs(repo+"/.git/dstask/ids.bin")
    if kind=="state-empty": open(repo+"/.git/dstask/state.bin","wb").close()
    if kind=="ids-empty": open(repo+"/.git/dstask/ids.bin","wb").close()
    if kind=="state-garbage": open(repo+"/.git/dstask/state.bin","wb").write(b"garbage")
    if kind=="ids-garbage": open(repo+"/.git/dstask/ids.bin","wb").write(b"garbage")
    if kind=="state-random": open(repo+"/.git/dstask/state.bin","wb").write(os.urandom(100))
    if kind=="ids-wrongtype":
        # copy a valid state gob into ids and vice versa later
        pass
    print("\n",kind); run(repo)
