repo=seed(); env=dict(os.environ); env["DSTASK_GIT_REPO"]=repo; subprocess.run(["./executable","add","x"],capture_output=True,env=env); subprocess.run(["./executable","context","+x"],capture_output=True,env=env)
ids=open(repo+"/.git/dstask/ids.bin","rb").read(); state=open(repo+"/.git/dstask/state.bin","rb").read(); open(repo+"/.git/dstask/ids.bin","wb").write(state); print("\nids=state gob"); run(repo)
open(repo+"/.git/dstask/ids.bin","wb").write(ids); open(repo+"/.git/dstask/state.bin","wb").write(ids); print("\nstate=ids gob"); run(repo)
