)

func MustFail(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "\x1b[31m"+format+"\x1b[0m\n", args...)
	os.Exit(1)
}

func ConfirmOrAbort(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, format+" [y/n] ", args...)
	reader := bufio.NewReader(os.Stdin)
	response, err := reader.ReadString('\n')
	if err != nil {
		panic(err)
	}
	response = strings.ToLower(strings.TrimSpace(response))
	if !strings.HasPrefix(response, "y") {
		MustFail("Aborted.")
	}
}

type winsize struct {
	Rows uint16
	Cols uint16
	X    uint16
	Y    uint16
}

func isTerminal(fd uintptr) bool {
	var termios [64]byte
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios[0])))
	return errno == 0
}

func IsTTY() bool {
	if os.Getenv("DSTASK_FAKE_PTY") != "" {
		return true
	}
	return isTerminal(os.Stdout.Fd())
}

func isStdoutTerminal() bool {
	return isTerminal(os.Stdout.Fd())
}

