package dstask

import (
	"encoding/gob"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

func getRepoPath() string {
	if p := os.Getenv("DSTASK_GIT_REPO"); p != "" {
		return p
	}
	return filepath.Join(os.Getenv("HOME"), ".dstask")
}

func mustHaveGit() {
	if _, err := exec.LookPath("git"); err != nil {
		MustFail("git required, please install")
	}
}

func ensureGitRepo() {
	if _, err := os.Stat(filepath.Join(repoPath, ".git")); os.IsNotExist(err) {
		if err := os.Mkdir(repoPath, 0700); err != nil {
			MustFail("Failed to create directory in git repository")
		}
		cmd := exec.Command("git", "init", repoPath)
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		cmd.Stdin = os.Stdin
		if err := cmd.Run(); err != nil {
			MustFail("Failed to run git cmd.")
		}
		os.Stdout.WriteString("\nAdd a remote repository with:\n\n\tdstask git remote add origin <repo>\n\n")
	}
}

func runGitCmd(args ...string) {
	cmd := exec.Command("git", args...)
	cmd.Dir = repoPath
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Stdin = os.Stdin
	if err := cmd.Run(); err != nil {
		MustFail("Failed to run git cmd.")
	}
}

func statePath() string {
	return filepath.Join(repoPath, ".git", "dstask", "state.bin")
}

func idsPath() string {
	return filepath.Join(repoPath, ".git", "dstask", "ids.bin")
}

func loadGob(path string, target interface{}) {
	f, err := os.Open(path)
	if err != nil {
		if os.IsNotExist(err) {
			return
		}
		MustFail("Failed to open %s for reading: %s", path, "")
	}
	defer f.Close()
	if err := gob.NewDecoder(f).Decode(target); err != nil {
		MustFail("Failed to parse state gob: %s, %s", path, err)
	}
}

func saveGob(path string, data interface{}) {
	_ = os.MkdirAll(filepath.Dir(path), 0755)
	f, err := os.Create(path)
	if err != nil {
		MustFail("Failed to open %s for writing: %s", path, "")
	}
	defer f.Close()
	_ = gob.NewEncoder(f).Encode(data)
}

func LoadState() State {
	var state State
	loadGob(statePath(), &state)
	if raw := os.Getenv("DSTASK_CONTEXT"); raw != "" {
		state.contextFromEnv = true
		state.Context = ParseQuery(strings.Fields(raw))
	}
	return state
}

func SaveState(state State) {
	saveGob(statePath(), state)
}
