	}
	for _, t := range q.AntiTags {
		parts = append(parts, "-"+t)
	}
	if q.Project != "" {
		parts = append(parts, "project:"+q.Project)
	}
	for _, p := range q.AntiProjects {
		parts = append(parts, "-project:"+p)
	}
	if !q.Due.IsZero() {
		if q.DateFilter != "" {
			parts = append(parts, fmt.Sprintf("due.%s:%s", q.DateFilter, q.Due.Format("2006-01-02")))
		} else {
			parts = append(parts, "due:"+q.Due.Format("2006-01-02"))
		}
	}
	if q.Priority != "" {
		parts = append(parts, q.Priority)
	}
	if q.Template > 0 {
		parts = append(parts, fmt.Sprintf("template:%d", q.Template))
	}
	if q.Text != "" {
		parts = append(parts, "\""+q.Text+"\"")
	}
	return strings.Join(parts, " ")
}

func (q *Query) Apply(q2 Query) error {
	q.Tags = append(q.Tags, q2.Tags...)
	q.AntiTags = append(q.AntiTags, q2.AntiTags...)
	if q2.Project != "" {
		if q.Project != "" && q.Project != q2.Project {
			return errors.New("Could not apply q2, project conflict")
		}
		q.Project = q2.Project
	}
	q.AntiProjects = append(q.AntiProjects, q2.AntiProjects...)
	if !q2.Due.IsZero() {
		if !q.Due.IsZero() && !q.Due.Equal(q2.Due) {
			return errors.New("Could not apply q2, date filter conflict")
		}
		q.Due = q2.Due
		q.DateFilter = q2.DateFilter
	}
	if q2.Priority != "" {
		if q.Priority != "" {
			return errors.New("Could not apply q2, priority conflict")
		}
		q.Priority = q2.Priority
	}
	return nil
}

func (q Query) HasOperators() bool {
	return len(q.Tags) > 0 || len(q.AntiTags) > 0 || q.Project != "" ||
		len(q.AntiProjects) > 0 || !q.Due.IsZero() || q.Priority != "" || q.Template != 0
}

func (q Query) MustNoOperators() {
	if q.HasOperators() {
		MustFail("operators not valid in this context")
	}
}

func (q Query) MustHaveIDs() {
	if len(q.IDs) == 0 {
		MustFail("no ID(s) specified")
	}
}

func (q Query) MustHaveOperators() {
	if !q.HasOperators() {
		MustFail("no operations specified")
	}
}

func applyContext(q *Query, state State) {
	if q.IgnoreContext {
		return
	}
	if err := q.Apply(state.Context); err != nil {
		MustFail("%s", err.Error())
	}
}

func matchesQuery(task *Task, q Query) bool {
	if len(q.IDs) > 0 {
		found := false
		for _, id := range q.IDs {
			if task.ID == id {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	for _, t := range q.Tags {
		if !hasTag(task, t) {
			return false
		}
	}
	for _, t := range q.AntiTags {
		if hasTag(task, t) {
			return false
		}
	}
	if q.Project != "" && task.Project != q.Project {
		return false
	}
	for _, p := range q.AntiProjects {
		if task.Project == p {
			return false
		}
	}
	if q.Priority != "" && task.Priority != q.Priority {
		return false
	}
	if !q.Due.IsZero() {
		if task.Due.IsZero() {
			return false
		}
		switch q.DateFilter {
		case "before":
			if task.Due.After(q.Due) {
				return false
			}
		case "after":
			if task.Due.Before(q.Due) {
				return false
			}
		default:
			if !task.Due.Equal(q.Due) {
				return false
			}
		}
	}
	if q.Text != "" {
		needle := strings.ToLower(q.Text)
		if !strings.Contains(strings.ToLower(task.Summary), needle) &&
			!strings.Contains(strings.ToLower(task.Notes), needle) {
			return false
		}
	}
	return true
}

func hasTag(task *Task, tag string) bool {
	for _, t := range task.Tags {
		if t == tag {
			return true
		}
	}
	return false
}
