	if q.HasOperators() {
		MustFail("operators not valid in this context")
	}
}

func (q Query) MustHaveIDs() {
	if len(q.IDs) == 0 {
		MustFail("no ID(s) specified")
	}
}

func (q Query) MustHaveOperators() {
	if !q.HasOperators() {
		MustFail("no operations specified")
	}
}

func applyContext(q *Query, state State) {
	if q.IgnoreContext {
		return
	}
	if err := q.Apply(state.Context); err != nil {
		MustFail("%s", err.Error())
	}
}

func matchesQuery(task *Task, q Query) bool {
	if len(q.IDs) > 0 {
		found := false
		for _, id := range q.IDs {
			if task.ID == id {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	for _, t := range q.Tags {
		if !hasTag(task, t) {
			return false
		}
	}
	for _, t := range q.AntiTags {
		if hasTag(task, t) {
			return false
		}
	}
	if q.Project != "" && task.Project != q.Project {
		return false
	}
	for _, p := range q.AntiProjects {
		if task.Project == p {
			return false
		}
	}
	if q.Priority != "" && task.Priority != q.Priority {
		return false
	}
	if !q.Due.IsZero() {
		if task.Due.IsZero() {
			return false
		}
		switch q.DateFilter {
		case "before":
			if task.Due.After(q.Due) {
				return false
			}
		case "after":
			if task.Due.Before(q.Due) {
				return false
			}
		default:
			if !task.Due.Equal(q.Due) {
				return false
			}
		}
	}
	if q.Text != "" {
		needle := strings.ToLower(q.Text)
		if !strings.Contains(strings.ToLower(task.Summary), needle) &&
			!strings.Contains(strings.ToLower(task.Notes), needle) {
			return false
		}
	}
	return true
}

func hasTag(task *Task, tag string) bool {
	for _, t := range task.Tags {
		if t == tag {
			return true
		}
	}
	return false
}
