package dstask

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"time"
)

var commandAliases = map[string]string{
	"next":              "next",
	"add":               "add",
	"rm":                "remove",
	"remove":            "remove",
	"template":          "template",
	"log":               "log",
	"start":             "start",
	"note":              "note",
	"notes":             "note",
	"stop":              "stop",
	"done":              "done",
	"resolve":           "done",
	"context":           "context",
	"modify":            "modify",
	"edit":              "edit",
	"undo":              "undo",
	"sync":              "sync",
	"open":              "open",
	"git":               "git",
	"show-next":         "next",
	"show-projects":     "show-projects",
	"show-tags":         "show-tags",
	"show-active":       "show-active",
	"show-paused":       "show-paused",
	"show-open":         "show-open",
	"show-resolved":     "show-resolved",
	"show-templates":    "show-templates",
	"show-unorganised":  "show-unorganised",
	"bash-completion":   "bash-completion",
	"fish-completion":   "fish-completion",
	"zsh-completion":    "zsh-completion",
	"help":              "help",
	"version":           "version",
	"_completions":      "_completions",
}

var completionCommands = []string{
	"next", "add", "rm", "remove", "template", "log", "start", "note", "notes",
	"stop", "done", "resolve", "context", "modify", "edit", "undo", "sync",
	"open", "git", "show-next", "show-projects", "show-tags", "show-active",
	"show-paused", "show-open", "show-resolved", "show-templates",
	"show-unorganised", "bash-completion", "fish-completion", "zsh-completion",
	"help", "version",
}

func ParseQuery(args []string) Query {
	var q Query
	var textWords []string
	var noteWords []string
	noteMode := false
	idsAllowed := true

	for _, arg := range args {
		if noteMode {
			noteWords = append(noteWords, arg)
			continue
		}
		if arg == "/" {
			noteMode = true
			idsAllowed = false
			continue
		}
		lower := strings.ToLower(arg)
		if q.Cmd == "" {
			if canon, ok := commandAliases[lower]; ok {
				q.Cmd = canon
				continue
			}
		}
		if idsAllowed {
			if id, err := strconv.Atoi(arg); err == nil {
				q.IDs = append(q.IDs, id)
				continue
			}
		}
		idsAllowed = false

		if arg == "--" {
			q.IgnoreContext = true
			continue
		}

		if strings.HasPrefix(lower, "due:") || strings.HasPrefix(lower, "due.") {
			if !q.Due.IsZero() {
				MustFail("Query should only have one due date")
			}
			parseDueToken(&q, lower)
			continue
		}

		if q.Priority == "" && (arg == "P0" || arg == "P1" || arg == "P2" || arg == "P3") {
			q.Priority = arg
			continue
		}

		if strings.HasPrefix(lower, "-project:") {
			q.AntiProjects = append(q.AntiProjects, lower[len("-project:"):])
			continue
		}
		if q.Project == "" && strings.HasPrefix(lower, "project:") {
			q.Project = lower[len("project:"):]
			continue
		}
		if q.Project == "" && strings.HasPrefix(lower, "+project:") {
			q.Project = lower[len("+project:"):]
			continue
		}

		if strings.HasPrefix(lower, "template:") {
			id, _ := strconv.Atoi(lower[len("template:"):])
			q.Template = id
			continue
		}

		if len(arg) > 1 && arg[0] == '+' {
			q.Tags = append(q.Tags, lower[1:])
			continue
		}
		if len(arg) > 1 && arg[0] == '-' {
			q.AntiTags = append(q.AntiTags, lower[1:])
			continue
		}

		textWords = append(textWords, arg)
	}

	q.Text = strings.Join(textWords, " ")
	q.Note = strings.Join(noteWords, " ")
	if q.Cmd == "" {
		q.Cmd = "next"
	}
	return q
}

func parseDueToken(q *Query, lower string) {
	filter := ""
	value := ""
	if strings.HasPrefix(lower, "due:") {
		value = lower[len("due:"):]
	} else {
		rest := lower[len("due."):]
		idx := strings.Index(rest, ":")
		if idx < 0 {
			MustFail("Invalid due query format: %s\nExpected format: due:YYYY-MM-DD, due:MM-DD, due:DD, due:next-monday, due:today, etc.", lower)
		}
		filter = rest[:idx]
		value = rest[idx+1:]
		if filter != "" && filter != "after" && filter != "before" && filter != "on" && filter != "in" {
			MustFail("Invalid date filter format: %s\nValid filters are: after, before, on, in", filter)
		}
	}
	if value == "overdue" {
		now := time.Now().UTC()
		q.Due = time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC)
		q.DateFilter = "before"
		return
	}
	due, err := parseDueDate(value)
	if err != nil {
		MustFail("Invalid due date format: %s\nExpected format: YYYY-MM-DD, MM-DD or DD, relative date like 'next-monday', 'today', etc.", value)
	}
	q.Due = due
	q.DateFilter = filter
}

var weekdayNames = map[string]time.Weekday{
	"mon":       time.Monday,
	"monday":    time.Monday,
	"tue":       time.Tuesday,
	"tues":      time.Tuesday,
	"tuesday":   time.Tuesday,
	"wed":       time.Wednesday,
	"wednesday": time.Wednesday,
	"thu":       time.Thursday,
	"thur":      time.Thursday,
	"thurs":     time.Thursday,
	"thursday":  time.Thursday,
	"fri":       time.Friday,
	"friday":    time.Friday,
	"sat":       time.Saturday,
	"saturday":  time.Saturday,
	"sun":       time.Sunday,
	"sunday":    time.Sunday,
}

func parseDueDate(value string) (time.Time, error) {
	now := time.Now().UTC()
	today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC)
	switch value {
	case "today":
		return today, nil
	case "tomorrow":
		return today.AddDate(0, 0, 1), nil
	case "yesterday":
		return today.AddDate(0, 0, -1), nil
	}
	if t, err := time.Parse("2006-01-02", value); err == nil {
		return t, nil
	}
	if t, err := time.Parse("2006-01-02", fmt.Sprintf("%d-%s", now.Year(), value)); err == nil {
		// Only accept MM-DD form here: length must be 5.
		if len(value) == 5 {
			return t, nil
		}
	}
	if len(value) <= 2 {
		if day, err := strconv.Atoi(value); err == nil {
			candidate := time.Date(now.Year(), now.Month(), day, 0, 0, 0, 0, time.UTC)
			if candidate.Day() == day && candidate.Month() == now.Month() {
				return candidate, nil
			}
		}
	}
	// Weekday forms.
	mode := ""
	name := value
	if strings.HasPrefix(value, "next-") {
		mode = "next"
		name = value[len("next-"):]
	} else if strings.HasPrefix(value, "last-") {
		mode = "last"
		name = value[len("last-"):]
	}
	if wd, ok := weekdayNames[name]; ok {
		todayWd := int(today.Weekday())
		target := int(wd)
		switch mode {
		case "next":
			days := (target - todayWd + 7) % 7
			if days == 0 {
				days = 7
			}
			return today.AddDate(0, 0, days), nil
		case "last":
			days := (todayWd - target + 7) % 7
			return today.AddDate(0, 0, -days), nil
		default:
			days := (target - todayWd + 7) % 7
			return today.AddDate(0, 0, days), nil
		}
	}
	return time.Time{}, errors.New("invalid due date")
}

func (q Query) String() string {
	var parts []string
	for _, id := range q.IDs {
		parts = append(parts, strconv.Itoa(id))
	}
	for _, t := range q.Tags {
		parts = append(parts, "+"+t)
	}
	for _, t := range q.AntiTags {
		parts = append(parts, "-"+t)
	}
	if q.Project != "" {
		parts = append(parts, "project:"+q.Project)
	}
	for _, p := range q.AntiProjects {
		parts = append(parts, "-project:"+p)
	}
	if !q.Due.IsZero() {
		if q.DateFilter != "" {
			parts = append(parts, fmt.Sprintf("due.%s:%s", q.DateFilter, q.Due.Format("2006-01-02")))
		} else {
			parts = append(parts, "due:"+q.Due.Format("2006-01-02"))
		}
	}
	if q.Priority != "" {
		parts = append(parts, q.Priority)
	}
	if q.Template > 0 {
		parts = append(parts, fmt.Sprintf("template:%d", q.Template))
	}
	if q.Text != "" {
		parts = append(parts, "\""+q.Text+"\"")
	}
	return strings.Join(parts, " ")
}

func (q *Query) Apply(q2 Query) error {
	q.Tags = append(q.Tags, q2.Tags...)
	q.AntiTags = append(q.AntiTags, q2.AntiTags...)
	if q2.Project != "" {
		if q.Project != "" && q.Project != q2.Project {
			return errors.New("Could not apply q2, project conflict")
		}
		q.Project = q2.Project
	}
	q.AntiProjects = append(q.AntiProjects, q2.AntiProjects...)
	if !q2.Due.IsZero() {
		if !q.Due.IsZero() && !q.Due.Equal(q2.Due) {
			return errors.New("Could not apply q2, date filter conflict")
		}
		q.Due = q2.Due
		q.DateFilter = q2.DateFilter
	}
	if q2.Priority != "" {
		if q.Priority != "" {
			return errors.New("Could not apply q2, priority conflict")
		}
		q.Priority = q2.Priority
	}
	return nil
}

func (q Query) HasOperators() bool {
	return len(q.Tags) > 0 || len(q.AntiTags) > 0 || q.Project != "" ||
		len(q.AntiProjects) > 0 || !q.Due.IsZero() || q.Priority != "" || q.Template != 0
}

func (q Query) MustNoOperators() {
	if q.HasOperators() {
		MustFail("operators not valid in this context")
	}
}

func (q Query) MustHaveIDs() {
	if len(q.IDs) == 0 {
		MustFail("no ID(s) specified")
	}
}

func (q Query) MustHaveOperators() {
	if !q.HasOperators() {
		MustFail("no operations specified")
	}
}

func applyContext(q *Query, state State) {
	if q.IgnoreContext {
		return
	}
	if err := q.Apply(state.Context); err != nil {
		MustFail("%s", err.Error())
	}
}

func matchesQuery(task *Task, q Query) bool {
	if len(q.IDs) > 0 {
		found := false
		for _, id := range q.IDs {
			if task.ID == id {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	for _, t := range q.Tags {
		if !hasTag(task, t) {
			return false
		}
	}
	for _, t := range q.AntiTags {
		if hasTag(task, t) {
			return false
		}
	}
	if q.Project != "" && task.Project != q.Project {
		return false
	}
	for _, p := range q.AntiProjects {
		if task.Project == p {
			return false
		}
	}
	if q.Priority != "" && task.Priority != q.Priority {
		return false
	}
	if !q.Due.IsZero() {
		if task.Due.IsZero() {
			return false
		}
		switch q.DateFilter {
		case "before":
			if task.Due.After(q.Due) {
				return false
			}
		case "after":
			if task.Due.Before(q.Due) {
				return false
			}
		default:
			if !task.Due.Equal(q.Due) {
				return false
			}
		}
	}
	if q.Text != "" {
		needle := strings.ToLower(q.Text)
		if !strings.Contains(strings.ToLower(task.Summary), needle) &&
			!strings.Contains(strings.ToLower(task.Notes), needle) {
			return false
		}
	}
	return true
}

func hasTag(task *Task, tag string) bool {
	for _, t := range task.Tags {
		if t == tag {
			return true
		}
	}
	return false
}
