	return dedentSequenceSections(buf.Bytes())
}

func dedentSequenceSections(data []byte) []byte {
	lines := strings.SplitAfter(string(data), "\n")
	var out []string
	inSeq := false
	for _, line := range lines {
		trimmed := strings.TrimSuffix(line, "\n")
		if strings.HasPrefix(trimmed, "tags:") || strings.HasPrefix(trimmed, "subtasks:") || strings.HasPrefix(trimmed, "dependencies:") {
