var uuidRegexp = regexp.MustCompile(`^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$`)

func newUUID() string {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		panic(err)
	}
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}

type TaskSet struct {
	Tasks []*Task
	ids   IdsMap
}

func LoadTasks(includeResolved bool) *TaskSet {
	ts := &TaskSet{ids: make(IdsMap)}
	seen := make(map[string]bool)
	for _, status := range loadOrder {
		if status == StatusResolved && !includeResolved {
			continue
		}
		dir := filepath.Join(repoPath, status)
		entries, err := os.ReadDir(dir)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			MustFail("%s", err.Error())
		}
		for _, entry := range entries {
			name := entry.Name()
			if strings.HasPrefix(name, ".") {
				continue
			}
			task, err := loadTask(filepath.Join(dir, name), name, status)
			if err != nil {
				log.Printf("error loading task: %s", err.Error())
				continue
			}
			if seen[task.UUID] {
				continue
			}
			seen[task.UUID] = true
			ts.Tasks = append(ts.Tasks, task)
		}
	}
	loadGob(idsPath(), &ts.ids)
	if ts.ids == nil {
		ts.ids = make(IdsMap)
	}
	ts.AssignIDs()
	return ts
}

func loadTask(path, name, status string) (*Task, error) {
	if len(name) != 40 {
		return nil, fmt.Errorf("filename does not encode UUID %s (wrong length)", name)
	}
	uuid := name[:36]
	if !uuidRegexp.MatchString(uuid) {
		return nil, fmt.Errorf("filename does not encode UUID %s", name)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("failed to read %s", name)
	}
	var task Task
	if err := yaml.Unmarshal(data, &task); err != nil {
		return nil, fmt.Errorf("failed to unmarshal %s", name)
	}
	task.UUID = uuid
	task.Status = status
	task.originalStatus = status
	task.Normalize()
	if err := task.Validate(); err != nil {
		return nil, err
	}
	return &task, nil
}

func (t *Task) Normalize() {
	if t.Tags != nil {
		seen := make(map[string]bool)
		tags := make([]string, 0, len(t.Tags))
		for _, tag := range t.Tags {
			tag = strings.ToLower(tag)
			if !seen[tag] {
				seen[tag] = true
				tags = append(tags, tag)
			}
		}
		sort.Strings(tags)
		t.Tags = tags
	}
	t.Project = strings.ToLower(t.Project)
	if t.Priority == "" {
		t.Priority = "P2"
	}
	if t.Created.IsZero() {
		t.Created = time.Now().UTC()
	}
}

func validStatus(s string) bool {
	for _, v := range allStatuses {
		if s == v {
			return true
		}
	}
	return false
}

func (t *Task) Validate() error {
	if !validStatus(t.Status) {
		return errors.New("invalid status specified on task")
	}
	if t.Priority != "P0" && t.Priority != "P1" && t.Priority != "P2" && t.Priority != "P3" {
		return errors.New("invalid priority specified")
	}
	for _, dep := range t.Dependencies {
		if !uuidRegexp.MatchString(dep) {
			return errors.New("invalid dependency UUID4")
		}
	}
	return nil
}

func validTransition(from, to string) bool {
	if from == to {
		return true
	}
	switch from {
	case StatusPending:
		return to == StatusActive || to == StatusTemplate || to == StatusResolved
	case StatusActive:
		return to == StatusPaused || to == StatusResolved
	case StatusPaused:
		return to == StatusActive || to == StatusResolved
	}
	return false
}

func (t *Task) ChangeStatus(newStatus string) {
	if !validTransition(t.Status, newStatus) {
		MustFail("invalid state transition: %s -> %s", t.Status, newStatus)
	}
	t.Status = newStatus
	if newStatus == StatusResolved {
		t.Resolved = time.Now().UTC()
	}
}

func (ts *TaskSet) AssignIDs() {
	used := make(map[int]bool)
	for _, task := range ts.Tasks {
		if task.Status == StatusResolved {
			task.ID = 0
			continue
		}
		if id, ok := ts.ids[task.UUID]; ok && !used[id] {
			task.ID = id
		} else {
			id := 1
			for used[id] {
				id++
			}
			task.ID = id
			ts.ids[task.UUID] = id
		}
		used[task.ID] = true
	}
}

func (ts *TaskSet) AddTask(task *Task) {
	ts.Tasks = append(ts.Tasks, task)
	ts.AssignIDs()
}

