		for _, existing := range t.Tags {
			if existing != tag {
				newTags = append(newTags, existing)
			}
		}
		filtered = newTags
		t.Tags = filtered
	}
	if q.Project != "" {
		t.Project = q.Project
	}
	for _, p := range q.AntiProjects {
		if t.Project == p {
			t.Project = ""
		}
	}
	if q.Priority != "" {
		t.Priority = q.Priority
	}
	if !q.Due.IsZero() {
		t.Due = q.Due
	}
	appendNoteSmart(t, q.Note)
	t.Normalize()
}

func newTaskFromQuery(q Query, includeDue bool, includeNote bool) *Task {
	tags := make([]string, 0, len(q.Tags))
	tags = append(tags, q.Tags...)
	task := &Task{
		UUID:         newUUID(),
		Status:       StatusPending,
		Summary:      q.Text,
		Tags:         tags,
		Project:      q.Project,
		Priority:     q.Priority,
		Subtasks:     make([]SubTask, 0),
		Dependencies: make([]string, 0),
		Created:      time.Now().UTC(),
	}
	if includeNote {
		task.Notes = q.Note
	}
	if includeDue {
		task.Due = q.Due
	}
	if task.Priority == "" {
		task.Priority = "P2"
	}
	task.Normalize()
	return task
}

func cloneTask(t *Task) *Task {
	c := *t
	if t.Tags != nil {
		c.Tags = append([]string{}, t.Tags...)
	}
	if t.Subtasks != nil {
		c.Subtasks = append([]SubTask{}, t.Subtasks...)
	}
	if t.Dependencies != nil {
		c.Dependencies = append([]string{}, t.Dependencies...)
	}
	c.originalStatus = ""
	return &c
}

func (ts *TaskSet) Projects() []*Project {
	byName := make(map[string]*Project)
	for _, t := range ts.Tasks {
		if t.Project == "" {
			continue
		}
		p, ok := byName[t.Project]
		if !ok {
			p = &Project{Name: t.Project, Created: t.Created, Priority: "P3"}
			byName[t.Project] = p
		}
		p.TaskCount++
		if t.Status == StatusResolved {
			p.ResolvedCount++
			if t.Resolved.After(p.Resolved) {
				p.Resolved = t.Resolved
			}
		} else if t.Priority < p.Priority {
			p.Priority = t.Priority
		}
		if t.Created.Before(p.Created) {
			p.Created = t.Created
		}
		if t.Status == StatusActive {
			p.Active = true
		}
	}
	out := make([]*Project, 0, len(byName))
	for _, p := range byName {
		out = append(out, p)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}
