func marshalYAML(v interface{}) []byte {
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	if err := enc.Encode(v); err != nil {
		panic(err)
	}
	_ = enc.Close()
	return dedentSequenceSections(buf.Bytes())
}

func dedentSequenceSections(data []byte) []byte {
	lines := strings.SplitAfter(string(data), "\n")
	var out []string
	inSeq := false
	for _, line := range lines {
		trimmed := strings.TrimSuffix(line, "\n")
		if strings.HasPrefix(trimmed, "tags:") || strings.HasPrefix(trimmed, "subtasks:") || strings.HasPrefix(trimmed, "dependencies:") {
			inSeq = true
			out = append(out, line)
			continue
		}
		if inSeq && trimmed != "" && !strings.HasPrefix(trimmed, " ") {
			inSeq = false
		}
		if inSeq && strings.HasPrefix(line, "  ") {
			line = line[2:]
		}
		out = append(out, line)
	}
	return []byte(strings.Join(out, ""))
}

func (t *Task) diskYAML() taskDiskYAML {
