func (ts *TaskSet) SaveTask(task *Task, message string) {
	ensureDirs()
	task.Normalize()
	if err := task.Validate(); err != nil {
		MustFail("%s, task %s", err.Error(), task.UUID)
	}
	if task.originalStatus != "" && task.originalStatus != task.Status {
		_ = os.Remove(filepath.Join(repoPath, task.originalStatus, task.UUID+".yml"))
	}
	path := filepath.Join(repoPath, task.Status, task.UUID+".yml")
	data := marshalYAML(task.diskYAML())
	if err := os.WriteFile(path, data, 0600); err != nil {
		MustFail("Failed to write task %d: %s", task.ID, task.Summary)
	}
	if task.Status == StatusResolved {
		delete(ts.ids, task.UUID)
	} else if task.ID != 0 {
		ts.ids[task.UUID] = task.ID
	}
	saveGob(idsPath(), ts.ids)
	fmt.Printf("\n%s\n", message)
	gitCommit(message)
	task.originalStatus = task.Status
}

func (ts *TaskSet) DeleteTask(task *Task, message string) {
	ensureDirs()
	_ = os.Remove(filepath.Join(repoPath, task.Status, task.UUID+".yml"))
	delete(ts.ids, task.UUID)
	saveGob(idsPath(), ts.ids)
	fmt.Printf("\n%s\n", message)
	gitCommit(message)
