func gitCommit(message string) {
	fmt.Print("\x1b[38;5;245m")
	add := exec.Command("git", "add", ".")
	add.Dir = repoPath
	add.Stdout = os.Stdout
	add.Stderr = os.Stderr
	add.Stdin = os.Stdin
	if err := add.Run(); err != nil {
		MustFail("error: failed to add changes to repo: %s", err.Error())
	}
	diff := exec.Command("git", "diff", "--cached", "--quiet")
	diff.Dir = repoPath
	diff.Stdout = os.Stdout
	diff.Stderr = os.Stderr
	diff.Stdin = os.Stdin
	if err := diff.Run(); err == nil {
		fmt.Print("No changes detected\n\x1b[0m")
		return
	}
	commit := exec.Command("git", "commit", "-m", message)
	commit.Dir = repoPath
	commit.Stdout = os.Stdout
	commit.Stderr = os.Stderr
	commit.Stdin = os.Stdin
	if err := commit.Run(); err != nil {
		MustFail("error: failed to commit changes: %s", err.Error())
	}
	fmt.Print("\x1b[0m")
}

func sortTasks(tasks []*Task) {
	sort.SliceStable(tasks, func(i, j int) bool {
		if tasks[i].Priority != tasks[j].Priority {
			return tasks[i].Priority < tasks[j].Priority
		}
		return tasks[i].Created.Before(tasks[j].Created)
	})
