			MustFail("%s", err.Error())
		}
	}
	if len(effective.IDs) > 0 && effective.HasOperators() {
		MustFail("operators not valid when addressing task by ID")
	}
	out := make([]*Task, 0)
	for _, t := range tasks {
		if matchesQuery(t, effective) {
			out = append(out, t)
