func (t *Task) Modify(q Query) {
	// Add tags first, then remove anti-tags (so anti wins on conflicts).
	for _, tag := range q.Tags {
		if !hasTag(t, tag) {
			t.Tags = append(t.Tags, tag)
		}
	}
	for _, tag := range q.AntiTags {
		filtered := t.Tags[:0]
		// Rebuild to avoid mutating while ranging over a copy of the slice header.
		newTags := make([]string, 0, len(t.Tags))
		for _, existing := range t.Tags {
			if existing != tag {
				newTags = append(newTags, existing)
			}
		}
		filtered = newTags
		t.Tags = filtered
	}
	if q.Project != "" {
		t.Project = q.Project
	}
	for _, p := range q.AntiProjects {
		if t.Project == p {
			t.Project = ""
		}
	}
	if q.Priority != "" {
		t.Priority = q.Priority
	}
	if !q.Due.IsZero() {
		t.Due = q.Due
	}
	appendNoteSmart(t, q.Note)
	t.Normalize()
}

