package dstask

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"time"
	"unicode/utf8"
)

func printJSON(v interface{}) {
	data, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		panic(err)
	}
	fmt.Print(string(data))
}

func printActiveContext(state State) {
	s := state.Context.String()
	if s == "" {
		return
	}
	if state.contextFromEnv {
		fmt.Printf("\x1b[33mActive context (set by DSTASK_CONTEXT): %s\x1b[0m\n", s)
	} else {
		fmt.Printf("\x1b[33mActive context: %s\x1b[0m\n", s)
	}
}

func runeLen(s string) int {
	return utf8.RuneCountInString(s)
}

func truncRunes(s string, width int) string {
	if width <= 0 {
		return ""
	}
	r := []rune(s)
	if len(r) > width {
		r = r[:width]
	}
	return string(r)
}

func padRight(s string, width int) string {
	s = truncRunes(s, width)
	for runeLen(s) < width {
		s += " "
	}
	return s
}

func computeWidths(headers []string, rows [][]string, termWidth int) []int {
	widths := make([]int, len(headers))
	for i, h := range headers {
		widths[i] = runeLen(h)
	}
	for _, row := range rows {
		for i, cell := range row {
			if i < len(widths) && runeLen(cell) > widths[i] {
				widths[i] = runeLen(cell)
			}
		}
	}
	total := 0
	for _, w := range widths {
		total += w
	}
	if len(widths) > 1 {
		total += 2 * (len(widths) - 1)
	}
	for total > termWidth {
		maxIdx := 0
		for i, w := range widths {
			if w > widths[maxIdx] {
				maxIdx = i
			}
		}
		if widths[maxIdx] <= 0 {
			break
		}
		widths[maxIdx]--
		total--
	}
	return widths
}

func renderPlainTable(headers []string, rows [][]string, styles []string) {
	termWidth, _ := terminalSize()
	widths := computeWidths(headers, rows, termWidth)
	// Header.
	var b strings.Builder
	b.WriteString("\x1b[4;38;5;250;48;5;232m")
	for i, h := range headers {
		if i > 0 {
			b.WriteString("  ")
		}
		b.WriteString(padRight(h, widths[i]))
	}
	b.WriteString("\x1b[0m\n")
	os.Stdout.WriteString(b.String())
	for ri, row := range rows {
		style := ""
		if ri < len(styles) {
			style = styles[ri]
		}
		var rb strings.Builder
		rb.WriteString(style)
		for i, cell := range row {
			if i > 0 {
				rb.WriteString("  ")
			}
			rb.WriteString(padRight(cell, widths[i]))
		}
		rb.WriteString("\x1b[0m\n")
		os.Stdout.WriteString(rb.String())
	}
}

var normalFg = map[string]int{"P0": 160, "P1": 166, "P2": 250, "P3": 245}
var activeFg = map[string]int{"P0": 124, "P1": 130, "P2": 233, "P3": 238}

func effectivePriority(t *Task) string {
	p := t.Priority
	if !t.Due.IsZero() {
		now := time.Now().UTC()
		tomorrow := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC).AddDate(0, 0, 1)
		if t.Due.Before(tomorrow) && p > "P1" {
			p = "P1"
		}
	}
	return p
}

func taskStyle(t *Task, idx int) (string, int) {
	ep := effectivePriority(t)
	var fg, bg int
	if t.Status == StatusActive {
		fg = activeFg[ep]
		bg = 250
	} else if t.Status == StatusPaused {
		fg = normalFg[ep]
		bg = 236
	} else {
		fg = normalFg[ep]
		if idx%2 == 0 {
			bg = 233
		} else {
			bg = 232
		}
	}
	return fmt.Sprintf("\x1b[0;38;5;%d;48;5;%dm", fg, bg), fg
}

func formatDue(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	now := time.Now().UTC()
