	for i, h := range headers {
		if i > 0 {
			b.WriteString("  ")
		}
		b.WriteString(padRight(h, widths[i]))
	}
	b.WriteString("\x1b[0m\n")
	os.Stdout.WriteString(b.String())
	for ri, row := range rows {
		style := ""
		if ri < len(styles) {
			style = styles[ri]
		}
		var rb strings.Builder
		rb.WriteString(style)
		for i, cell := range row {
			if i > 0 {
				rb.WriteString("  ")
			}
			rb.WriteString(padRight(cell, widths[i]))
		}
		rb.WriteString("\x1b[0m\n")
		os.Stdout.WriteString(rb.String())
	}
}

var normalFg = map[string]int{"P0": 160, "P1": 166, "P2": 250, "P3": 245}
var activeFg = map[string]int{"P0": 124, "P1": 130, "P2": 233, "P3": 238}

func effectivePriority(t *Task) string {
	p := t.Priority
	if !t.Due.IsZero() {
		now := time.Now().UTC()
		tomorrow := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC).AddDate(0, 0, 1)
		if t.Due.Before(tomorrow) && p > "P1" {
			p = "P1"
		}
	}
	return p
}

func taskStyle(t *Task, idx int) (string, int) {
	ep := effectivePriority(t)
	var fg, bg int
	if t.Status == StatusActive {
		fg = activeFg[ep]
		bg = 250
	} else if t.Status == StatusPaused {
		fg = normalFg[ep]
		bg = 236
	} else {
		fg = normalFg[ep]
		if idx%2 == 0 {
			bg = 233
		} else {
			bg = 232
		}
	}
	return fmt.Sprintf("\x1b[0;38;5;%d;48;5;%dm", fg, bg), fg
}

func formatDue(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	now := time.Now().UTC()
	today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC)
	dueDay := time.Date(t.Year(), t.Month(), t.Day(), 0, 0, 0, 0, time.UTC)
	days := int(dueDay.Sub(today).Hours() / 24)
	switch {
	case days == -1:
		return "yesterday"
	case days == 0:
		return "today"
	case days == 1:
		return "tomorrow"
	case days >= 2 && days <= 6:
		return t.Format("Mon 2")
	default:
		if t.Year() != now.Year() {
			return t.Format("_2 Jan 2006")
		}
		return t.Format("_2 Jan")
	}
}

func lastLine(s string) string {
	if idx := strings.LastIndex(s, "\n"); idx >= 0 {
		return s[idx+1:]
	}
	return s
}

func renderTasksTable(tasks []*Task, resolvedMode bool) {
	termWidth, _ := terminalSize()
	firstHeader := "ID"
	if resolvedMode {
		firstHeader = "Resolved"
	}
	headers := []string{firstHeader, "Priority", "Tags", "Due", "Project", "Summary"}
	// Build plain rows for first five columns and effective summary lengths.
	type rowData struct {
		cells []string // first five columns
		task  *Task
		style string
		fg    int
	}
	rowsData := make([]rowData, len(tasks))
	plainRows := make([][]string, len(tasks))
	for i, t := range tasks {
		first := fmt.Sprintf("%d", t.ID)
		if resolvedMode {
			first = t.Resolved.Format("Mon 2")
		}
		cells := []string{first, t.Priority, strings.Join(t.Tags, " "), formatDue(t.Due), t.Project}
		style, fg := taskStyle(t, i)
		rowsData[i] = rowData{cells: cells, task: t, style: style, fg: fg}
		effSummaryLen := runeLen(t.Summary)
		if t.Notes != "" {
			effSummaryLen += 1 + runeLen(lastLine(t.Notes)) + 2
		}
		plainRows[i] = append(append([]string{}, cells...), strings.Repeat(" ", effSummaryLen))
	}
	widths := computeWidths(headers, plainRows, termWidth)
	// Header.
	os.Stdout.WriteString("\x1b[4;38;5;250;48;5;232m")
	for i, h := range headers {
		if i > 0 {
			os.Stdout.WriteString("  ")
		}
		os.Stdout.WriteString(padRight(h, widths[i]))
	}
	os.Stdout.WriteString("\x1b[0m\n")
	for _, rd := range rowsData {
		os.Stdout.WriteString(rd.style)
		for i, cell := range rd.cells {
			if i > 0 {
				os.Stdout.WriteString("  ")
			}
			os.Stdout.WriteString(padRight(cell, widths[i]))
		}
		os.Stdout.WriteString("  ")
		summaryWidth := widths[5]
		summary := rd.task.Summary
		if runeLen(summary) >= summaryWidth {
			os.Stdout.WriteString(truncRunes(summary, summaryWidth))
		} else if rd.task.Notes != "" && summaryWidth-runeLen(summary) > 1 {
			remaining := summaryWidth - runeLen(summary)
			segment := " " + lastLine(rd.task.Notes)
			os.Stdout.WriteString(summary)
			os.Stdout.WriteString("\x1b[38;5;240m")
			os.Stdout.WriteString(padRight(segment, remaining))
			os.Stdout.WriteString(fmt.Sprintf("\x1b[38;5;%dm", rd.fg))
		} else {
			os.Stdout.WriteString(padRight(summary, summaryWidth))
		}
		os.Stdout.WriteString("\x1b[0m\n")
	}
}

func printNotes(t *Task) {
	if t.Notes != "" {
		fmt.Printf("\nNotes on task %d:\n\x1b[38;5;245m%s\x1b[0m\n\n", t.ID, t.Notes)
	}
}

func (ts *TaskSet) printCriticalWarning(displayed []*Task) {
	full := 0
	for _, t := range ts.Tasks {
		if openStatuses[t.Status] && t.Priority == "P0" {
			full++
		}
	}
	shown := 0
	for _, t := range displayed {
		if t.Priority == "P0" {
			shown++
		}
	}
	if n := full - shown; n > 0 {
		fmt.Printf("\x1b[38;5;160m%d critical task(s) outside this context! Use `dstask -- P0` to see them.\x1b[0m\n", n)
	}
}

func (ts *TaskSet) DisplayTasks(tasks []*Task, state State, q Query, truncate bool) {
	if !IsTTY() {
		if tasks == nil {
			tasks = make([]*Task, 0)
		}
		printJSON(tasks)
		return
	}
	if !q.IgnoreContext {
		printActiveContext(state)
	}
	if len(tasks) == 0 {
		MustFail("No matching tasks in given context or filter.")
	}
	if len(tasks) == 1 {
		displayTask(tasks[0])
		printNotes(tasks[0])
		ts.printCriticalWarning(tasks)
		return
	}
	shown := tasks
	truncated := false
	if truncate {
		_, height := terminalSize()
		limit := height - 9
		if limit < 8 {
			limit = 8
		}
		if len(tasks) > limit {
			shown = tasks[:limit]
			truncated = true
		}
	}
	renderTasksTable(shown, false)
	if truncated {
		fmt.Printf("\n%d/%d tasks shown.\n", len(shown), len(tasks))
	} else {
		fmt.Printf("\n%d tasks.\n", len(tasks))
	}
	ts.printCriticalWarning(tasks)
}

func displayTask(t *Task) {
	rows := [][]string{
		{"ID", fmt.Sprintf("%d", t.ID)},
		{"Priority", t.Priority},
		{"Summary", t.Summary},
		{"Status", t.Status},
		{"Project", t.Project},
		{"Tags", strings.Join(t.Tags, ", ")},
		{"UUID", t.UUID},
		{"Created", t.Created.String()},
	}
	if !t.Resolved.IsZero() {
		rows = append(rows, []string{"Resolved", t.Resolved.String()})
	}
	if !t.Due.IsZero() {
		rows = append(rows, []string{"Due", t.Due.String()})
	}
	styles := make([]string, len(rows))
	for i := range rows {
		bg := 233
		if i%2 == 1 {
			bg = 232
		}
		styles[i] = fmt.Sprintf("\x1b[0;38;5;250;48;5;%dm", bg)
	}
	renderPlainTable([]string{"Name", "Value"}, rows, styles)
}

func (ts *TaskSet) DisplayProjects(projects []*Project) {
	if !IsTTY() {
		if projects == nil {
			projects = make([]*Project, 0)
		}
		printJSON(projects)
		return
	}
	var rows [][]string
	var styles []string
	displayIdx := 0
	for _, p := range projects {
		if p.ResolvedCount >= p.TaskCount {
			continue
		}
		rows = append(rows, []string{p.Name, fmt.Sprintf("%d/%d", p.ResolvedCount, p.TaskCount), p.Created.Format("Mon 2 Jan 2006")})
		if p.Active {
			styles = append(styles, "\x1b[0;38;5;233;48;5;250m")
		} else {
			bg := 233
			if displayIdx%2 == 1 {
				bg = 232
			}
			styles = append(styles, fmt.Sprintf("\x1b[0;38;5;%d;48;5;%dm", normalFg[p.Priority], bg))
		}
		displayIdx++
	}
	renderPlainTable([]string{"Name", "Progress", "Created"}, rows, styles)
}

func (ts *TaskSet) DisplayResolved(tasks []*Task) {
	if !isStdoutTerminal() {
		if tasks == nil {
			tasks = make([]*Task, 0)
		}
		printJSON(tasks)
		return
	}
	// Group by ISO week.
	var group []*Task
	var groupYear, groupWeek int
	flush := func() {
		if len(group) == 0 {
			return
		}
		first := group[0]
		_, week := first.Resolved.ISOWeek()
		fmt.Printf("\n\n> Week %d, starting %s\n\n", week, first.Resolved.Format("Mon 2 Jan 2006"))
		renderTasksTable(group, true)
		group = nil
	}
	for _, t := range tasks {
		y, w := t.Resolved.ISOWeek()
		if len(group) > 0 && (y != groupYear || w != groupWeek) {
			flush()
		}
		if len(group) == 0 {
			groupYear, groupWeek = y, w
		}
		group = append(group, t)
	}
	flush()
	fmt.Printf("%d tasks.\n", len(tasks))
}
