func mustNoOperatorsWithIDs(q Query) {
	if len(q.IDs) > 0 && q.HasOperators() {
		MustFail("operators not valid when addressing task by ID")
	}
}

func CommandAdd(ts *TaskSet, state State, q Query) {
	if !q.IgnoreContext {
		printActiveContext(state)
	}
	if q.DateFilter == "before" || q.DateFilter == "after" {
		MustFail("cannot use date filter with add command")
	}
	if q.Text == "" && q.Template == 0 {
		MustFail("task description or template required")
	}
	applyContext(&q, state)
	if q.Template != 0 {
		src := ts.GetTaskByID(q.Template)
		task := cloneTask(src)
		task.UUID = newUUID()
		task.ID = 0
		task.Status = StatusPending
		task.Created = time.Now().UTC()
		task.Resolved = time.Time{}
		if q.Text != "" {
			task.Summary = q.Text
		}
		task.Modify(q)
		ts.AddTask(task)
		ts.SaveTask(task, fmt.Sprintf("Added %d: %s", task.ID, task.Summary))
		if src.Status != StatusTemplate {
			fmt.Print("\nYou've copied an open task!\nTo learn more about creating templates enter 'dstask help template'\n\n")
		}
		return
	}
	task := newTaskFromQuery(q, true, true)
	ts.AddTask(task)
	ts.SaveTask(task, fmt.Sprintf("Added %d: %s", task.ID, task.Summary))
}

func CommandLog(ts *TaskSet, state State, q Query) {
	if !q.IgnoreContext {
		printActiveContext(state)
	}
	if q.Text == "" {
		MustFail("task description required")
	}
	applyContext(&q, state)
	task := newTaskFromQuery(q, true, false)
	task.Status = StatusResolved
	task.Resolved = time.Now().UTC()
	task.Created = time.Now().UTC()
	ts.AddTask(task)
	ts.SaveTask(task, "Logged "+task.Summary)
}

func CommandTemplate(ts *TaskSet, state State, q Query) {
	if len(q.IDs) > 0 {
		for _, id := range q.IDs {
			task := ts.GetTaskByID(id)
			task.ChangeStatus(StatusTemplate)
			ts.SaveTask(task, fmt.Sprintf("Changed %d: %s to Template", task.ID, task.Summary))
		}
		return
	}
	if q.Text == "" {
		return
	}
	applyContext(&q, state)
	task := newTaskFromQuery(q, true, true)
	task.Status = StatusTemplate
	ts.AddTask(task)
	ts.SaveTask(task, fmt.Sprintf("Created Template %d: %s", task.ID, task.Summary))
}

func CommandStart(ts *TaskSet, state State, q Query) {
	if q.Template != 0 {
		MustFail("templates not yet supported for start command")
	}
	if len(q.IDs) > 0 {
		for _, id := range q.IDs {
			task := ts.GetTaskByID(id)
			if q.Text != "" {
				task.Notes += "\n" + q.Text
			}
			task.ChangeStatus(StatusActive)
			ts.SaveTask(task, fmt.Sprintf("Started %d: %s", task.ID, task.Summary))
			printNotes(task)
		}
		return
	}
	if q.Text == "" {
		MustFail("nothing to do -- specify an ID or describe a task")
	}
	applyContext(&q, state)
	task := newTaskFromQuery(q, false, true)
	task.Status = StatusActive
	ts.AddTask(task)
	ts.SaveTask(task, fmt.Sprintf("Added and started %d: %s", task.ID, task.Summary))
}

func CommandStop(ts *TaskSet, state State, q Query) {
	q.MustNoOperators()
	q.MustHaveIDs()
	for _, id := range q.IDs {
		task := ts.GetTaskByID(id)
		if q.Text != "" {
			task.Notes += "\n" + q.Text
		}
		task.ChangeStatus(StatusPaused)
		ts.SaveTask(task, fmt.Sprintf("Stopped %d: %s", task.ID, task.Summary))
	}
}

func CommandDone(ts *TaskSet, state State, q Query) {
	q.MustNoOperators()
	q.MustHaveIDs()
	for _, id := range q.IDs {
		task := ts.GetTaskByID(id)
		if q.Text != "" {
			task.Notes += "\n" + q.Text
		}
		task.ChangeStatus(StatusResolved)
		ts.SaveTask(task, fmt.Sprintf("Resolved %d: %s", task.ID, task.Summary))
	}
}

func CommandModify(ts *TaskSet, state State, q Query) {
	q.MustHaveOperators()
	if len(q.IDs) > 0 {
		for _, id := range q.IDs {
			task := ts.GetTaskByID(id)
			task.Modify(q)
			ts.SaveTask(task, fmt.Sprintf("Modified %d: %s", task.ID, task.Summary))
		}
		return
	}
	selQuery := Query{IgnoreContext: q.IgnoreContext}
	tasks := ts.FilterByQuery(ts.FilterOpen(), selQuery, state)
	if IsTTY() {
		ConfirmOrAbort("no IDs specified. Apply to all %d tasks in current ctx?", len(tasks))
	}
	for _, task := range tasks {
		task.Modify(q)
		ts.SaveTask(task, fmt.Sprintf("Modified %d: %s", task.ID, task.Summary))
	}
}

func CommandRemove(ts *TaskSet, state State, q Query) {
	q.MustHaveIDs()
	q.MustNoOperators()
	tasks := make([]*Task, 0, len(q.IDs))
	for _, id := range q.IDs {
		tasks = append(tasks, ts.GetTaskByID(id))
	}
	for _, task := range tasks {
		fmt.Printf("%d: %s\n", task.ID, task.Summary)
	}
	if IsTTY() {
		ConfirmOrAbort("\nThe above %d task(s) will be deleted without checking subtasks. Continue?", len(tasks))
	}
	for _, task := range tasks {
		msg := fmt.Sprintf("Removed: %d: %s", task.ID, task.Summary)
		if q.Text != "" {
			msg += "\n\n" + q.Text
		}
		ts.DeleteTask(task, msg)
	}
}

func slugify(s string) string {
	s = strings.ToLower(s)
	var b strings.Builder
	for _, r := range s {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') {
			b.WriteRune(r)
		} else {
			b.WriteRune('-')
		}
	}
	return b.String()
}

func runEditor(path string) {
	fields := strings.Fields(os.Getenv("EDITOR"))
	if len(fields) == 0 {
		MustFail("Failed to run $EDITOR")
	}
	args := append(append([]string{}, fields[1:]...), path)
	cmd := exec.Command(fields[0], args...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		MustFail("Failed to run $EDITOR")
	}
}

func CommandNote(ts *TaskSet, state State, q Query) {
	q.MustHaveIDs()
	q.MustNoOperators()
	if !IsTTY() {
		for _, id := range q.IDs {
			task := ts.GetTaskByID(id)
			fmt.Print(task.Notes)
		}
		return
	}
	for _, id := range q.IDs {
		task := ts.GetTaskByID(id)
		if q.Text != "" {
			appendNoteSmart(task, q.Text)
		} else {
			pattern := fmt.Sprintf("dstask.*.%d-%s.md", task.ID, slugify(task.Summary))
			f, err := os.CreateTemp("", pattern)
			if err != nil {
				MustFail("%s", err.Error())
			}
			path := f.Name()
			if _, err := f.WriteString(task.Notes); err != nil {
				MustFail("%s", err.Error())
			}
			_ = f.Close()
			runEditor(path)
			data, err := os.ReadFile(path)
			if err != nil {
				MustFail("%s", err.Error())
			}
			_ = os.Remove(path)
			task.Notes = string(data)
		}
		ts.SaveTask(task, fmt.Sprintf("Edit note %d: %s", task.ID, task.Summary))
	}
}

func CommandEdit(ts *TaskSet, state State, q Query) {
	q.MustNoOperators()
	q.MustHaveIDs()
	for _, id := range q.IDs {
		task := ts.GetTaskByID(id)
		origStatus := task.Status
		for {
			pattern := fmt.Sprintf("dstask.*.%d-%s.yml", task.ID, slugify(task.Summary))
			f, err := os.CreateTemp("", pattern)
			if err != nil {
				MustFail("%s", err.Error())
			}
			path := f.Name()
			if _, err := f.Write(marshalYAML(task.editYAML())); err != nil {
				MustFail("%s", err.Error())
			}
			_ = f.Close()
			runEditor(path)
			data, err := os.ReadFile(path)
			if err != nil {
				MustFail("%s", err.Error())
			}
			_ = os.Remove(path)
			if err := yaml.Unmarshal(data, task); err != nil {
				ConfirmOrAbort("Failed to unmarshal %s\nTry again?", err.Error())
				continue
			}
			break
		}
		task.Normalize()
		if err := task.Validate(); err != nil {
			MustFail("%s, task %s", err.Error(), task.UUID)
		}
		if task.Status != origStatus {
			target := task.Status
			task.Status = origStatus
			task.ChangeStatus(target)
		}
		ts.SaveTask(task, fmt.Sprintf("Edited %d: %s", task.ID, task.Summary))
	}
}

var urlRegexp = regexp.MustCompile(`(?i)(?:https?://|ftp://|www\.)[^\s<>"']+|[^\s<>"'@]+@[^\s<>"']+\.[^\s<>"']+|\b[a-z0-9.-]+\.[a-z]{2,}(?:/[^\s<>"']*)?`)

func extractURLs(s string) []string {
	matches := urlRegexp.FindAllString(s, -1)
	var out []string
	for _, m := range matches {
		m = trimURLPunctuation(m)
		if m != "" {
			out = append(out, m)
		}
	}
	return out
}

func trimURLPunctuation(u string) string {
	for len(u) > 0 {
		last := u[len(u)-1]
		switch last {
		case '.', ',', ';', ':', '!', '?':
			u = u[:len(u)-1]
		case ')':
			if strings.Count(u, "(") < strings.Count(u, ")") {
				u = u[:len(u)-1]
			} else {
				return u
			}
		case ']':
			if strings.Count(u, "[") < strings.Count(u, "]") {
				u = u[:len(u)-1]
			} else {
				return u
			}
		case '}':
			if strings.Count(u, "{") < strings.Count(u, "}") {
				u = u[:len(u)-1]
			} else {
				return u
			}
		case '\'', '"':
			u = u[:len(u)-1]
		default:
			return u
		}
	}
	return u
}

func CommandOpen(ts *TaskSet, state State, q Query) {
	q.MustHaveIDs()
	q.MustNoOperators()
	for _, id := range q.IDs {
		task := ts.GetTaskByID(id)
		urls := append(extractURLs(task.Summary), extractURLs(task.Notes)...)
		if len(urls) == 0 {
			MustFail("no URLs found in task %d", id)
		}
		for _, u := range urls {
			cmd := exec.Command("xdg-open", u)
			if err := cmd.Start(); err != nil {
				MustFail("Failed to open browser")
			}
		}
	}
}

func CommandContext(state State, q Query) {
	if len(os.Args) <= 2 {
		fmt.Println(state.Context.String())
		if !state.contextFromEnv {
			SaveState(state)
		}
		return
	}
	if state.contextFromEnv {
		MustFail("setting context not allowed while DSTASK_CONTEXT is set")
	}
	if len(os.Args) > 2 && os.Args[2] == "none" {
		state.Context = Query{}
		SaveState(state)
		return
	}
	if len(q.IDs) > 0 {
		MustFail("context cannot contain IDs")
	}
	if q.Text != "" {
		MustFail("context cannot contain text")
	}
	state.Context = q
	SaveState(state)
}

func CommandUndo() {
	n := 1
	if len(os.Args) > 2 {
		parsed, err := strconv.Atoi(os.Args[2])
		if err != nil {
			fmt.Fprint(os.Stderr, helpUndo)
			return
		}
		n = parsed
	}
	runGitCmd("revert", "--no-edit", fmt.Sprintf("HEAD~%d..", n))
}

