func mustNoOperatorsWithIDs(q Query) {
	if len(q.IDs) > 0 && q.HasOperators() {
		MustFail("operators not valid when addressing task by ID")
	}
}

func CommandAdd(ts *TaskSet, state State, q Query) {
	if !q.IgnoreContext {
		printActiveContext(state)
	}
	if q.DateFilter == "before" || q.DateFilter == "after" {
		MustFail("cannot use date filter with add command")
	}
	if q.Text == "" && q.Template == 0 {
		MustFail("task description or template required")
	}
	applyContext(&q, state)
	if q.Template != 0 {
		src := ts.GetTaskByID(q.Template)
		task := cloneTask(src)
		task.UUID = newUUID()
		task.ID = 0
		task.Status = StatusPending
		task.Created = time.Now().UTC()
		task.Resolved = time.Time{}
		if q.Text != "" {
			task.Summary = q.Text
		}
		task.Modify(q)
		ts.AddTask(task)
		ts.SaveTask(task, fmt.Sprintf("Added %d: %s", task.ID, task.Summary))
		if src.Status != StatusTemplate {
			fmt.Print("\nYou've copied an open task!\nTo learn more about creating templates enter 'dstask help template'\n\n")
		}
		return
	}
	task := newTaskFromQuery(q, true, true)
	ts.AddTask(task)
	ts.SaveTask(task, fmt.Sprintf("Added %d: %s", task.ID, task.Summary))
}

func CommandLog(ts *TaskSet, state State, q Query) {
	if !q.IgnoreContext {
		printActiveContext(state)
	}
	if q.Text == "" {
		MustFail("task description required")
	}
	applyContext(&q, state)
	task := newTaskFromQuery(q, true, false)
	task.Status = StatusResolved
	task.Resolved = time.Now().UTC()
	task.Created = time.Now().UTC()
	ts.AddTask(task)
	ts.SaveTask(task, "Logged "+task.Summary)
}

func CommandTemplate(ts *TaskSet, state State, q Query) {
	if len(q.IDs) > 0 {
		for _, id := range q.IDs {
			task := ts.GetTaskByID(id)
			task.ChangeStatus(StatusTemplate)
			ts.SaveTask(task, fmt.Sprintf("Changed %d: %s to Template", task.ID, task.Summary))
		}
		return
	}
	if q.Text == "" {
		return
	}
	applyContext(&q, state)
	task := newTaskFromQuery(q, true, true)
	task.Status = StatusTemplate
	ts.AddTask(task)
	ts.SaveTask(task, fmt.Sprintf("Created Template %d: %s", task.ID, task.Summary))
}

func CommandStart(ts *TaskSet, state State, q Query) {
	if q.Template != 0 {
		MustFail("templates not yet supported for start command")
	}
	if len(q.IDs) > 0 {
		for _, id := range q.IDs {
			task := ts.GetTaskByID(id)
			if q.Text != "" {
				task.Notes += "\n" + q.Text
			}
			task.ChangeStatus(StatusActive)
			ts.SaveTask(task, fmt.Sprintf("Started %d: %s", task.ID, task.Summary))
			printNotes(task)
		}
		return
	}
	if q.Text == "" {
		MustFail("nothing to do -- specify an ID or describe a task")
	}
	applyContext(&q, state)
	task := newTaskFromQuery(q, false, true)
	task.Status = StatusActive
	ts.AddTask(task)
	ts.SaveTask(task, fmt.Sprintf("Added and started %d: %s", task.ID, task.Summary))
}

func CommandStop(ts *TaskSet, state State, q Query) {
	q.MustNoOperators()
