func CommandShowProjects(ts *TaskSet, state State, q Query) {
	if q.HasOperators() || len(q.IDs) > 0 {
		MustFail("query/context not supported for show-projects")
	}
	ts.DisplayProjects(ts.Projects())
}

func CommandShowTags(ts *TaskSet, state State, q Query) {
	tasks := ts.FilterByQuery(ts.Tasks, q, state)
	set := make(map[string]bool)
	for _, t := range tasks {
		for _, tag := range t.Tags {
			set[tag] = true
		}
	}
	for tag := range set {
		fmt.Println(tag)
	}
}
