cat > dstask/completions.go <<'EOF'
package dstask

import (
	"fmt"
	"os"
	"sort"
	"strings"
)

// parseQueryNoDefault parses using ParseQuery but reports whether an explicit
// command was present by scanning tokens. ParseQuery defaults Cmd to next, so
// for completion purposes we reset Cmd to "" when no command token is present.
func parseForCompletion(args []string) Query {
	q := ParseQuery(args)
	explicit := false
	noteMode := false
	cmdFound := false
	for _, a := range args {
		if noteMode {
			continue
		}
		if a == "/" {
			noteMode = true
			continue
		}
		if !cmdFound {
			if _, ok := commandAliases[strings.ToLower(a)]; ok {
				explicit = true
				cmdFound = true
			}
		}
	}
	if !explicit {
		q.Cmd = ""
	}
	return q
}

func CommandCompletions(ts *TaskSet, state State, q Query) {
	raw := []string{}
	if len(os.Args) > 2 {
		raw = os.Args[2:]
	}
	prefix := ""
	var simArgs []string
	if len(raw) > 1 {
		simArgs = raw[1:]
		prefix = raw[len(raw)-1]
	}
	cq := parseForCompletion(simArgs)

	if cq.Cmd == "git" {
		return
	}

	var candidates []string
	if cq.Cmd == "help" {
		candidates = append(candidates, completionCommands...)
	} else {
		if cq.Cmd == "" {
			candidates = append(candidates, completionCommands...)
		}
		candidates = append(candidates, "P0", "P1", "P2", "P3")
		// Projects (from all loaded tasks), sorted by name via Projects().
		for _, p := range ts.Projects() {
			candidates = append(candidates, "project:"+p.Name)
			candidates = append(candidates, "-project:"+p.Name)
		}
		// Tags from a task pool.
		var pool []*Task
		if cq.Cmd == "context" {
			pool = ts.Tasks
		} else if cq.IgnoreContext {
			pool = ts.Tasks
		} else {
			pool = ts.FilterByQuery(ts.Tasks, Query{}, state)
		}
		sortTasks(append([]*Task{}, pool...))
		seenTags := make(map[string]bool)
		var tags []string
		sortedPool := append([]*Task{}, pool...)
		sortTasks(sortedPool)
		for _, t := range sortedPool {
			for _, tag := range t.Tags {
				if !seenTags[tag] {
					seenTags[tag] = true
					tags = append(tags, tag)
				}
			}
		}
		_ = sort.StringSlice{}
		for _, tag := range tags {
			candidates = append(candidates, "+"+tag)
			candidates = append(candidates, "-"+tag)
		}
	}

	present := make(map[string]bool)
	for _, a := range simArgs {
		present[a] = true
	}
	for _, c := range candidates {
		if present[c] {
			continue
		}
		if strings.HasPrefix(c, prefix) {
			fmt.Println(c)
		}
	}
}
