package dstask

import (
	"fmt"
	"os"
)

func Main() {
	query := ParseQuery(os.Args[1:])

	switch query.Cmd {
	case "help":
		PrintHelp()
		return
	case "version":
		fmt.Print("Version: Unknown\nGit commit: Unknown\nBuild date: Unknown\n")
		return
	case "bash-completion":
		fmt.Print(bashCompletionScript)
		return
	case "fish-completion":
		fmt.Print(fishCompletionScript)
		return
	case "zsh-completion":
		fmt.Print(zshCompletionScript)
		return
	}

	mustHaveGit()
	repoPath = getRepoPath()
	ensureGitRepo()

	switch query.Cmd {
	case "git":
		args := []string{}
		if len(os.Args) > 2 {
			args = os.Args[2:]
		}
		runGitCmd(args...)
		return
	case "sync":
		runGitCmd("pull")
		runGitCmd("push")
		return
	case "undo":
		CommandUndo()
		return
	}

	state := LoadState()

	if query.Cmd == "context" {
		CommandContext(state, query)
		return
	}

	includeResolved := query.Cmd == "show-resolved" || query.Cmd == "show-projects"
	ts := LoadTasks(includeResolved)

	switch query.Cmd {
	case "next":
		CommandNext(ts, state, query)
	case "add":
		CommandAdd(ts, state, query)
	case "template":
		CommandTemplate(ts, state, query)
	case "log":
		CommandLog(ts, state, query)
	case "start":
		CommandStart(ts, state, query)
	case "note":
		CommandNote(ts, state, query)
	case "stop":
		CommandStop(ts, state, query)
	case "done":
		CommandDone(ts, state, query)
	case "modify":
		CommandModify(ts, state, query)
	case "edit":
		CommandEdit(ts, state, query)
	case "open":
		CommandOpen(ts, state, query)
	case "remove":
		CommandRemove(ts, state, query)
	case "show-projects":
		CommandShowProjects(ts, state, query)
	case "show-tags":
		CommandShowTags(ts, state, query)
	case "show-active":
		CommandShowByStatus(ts, state, query, StatusActive)
	case "show-paused":
		CommandShowByStatus(ts, state, query, StatusPaused)
	case "show-open":
		CommandShowOpen(ts, state, query)
	case "show-resolved":
		CommandShowResolved(ts, state, query)
	case "show-templates":
		CommandShowTemplates(ts, state, query)
	case "show-unorganised":
		CommandShowUnorganised(ts, state, query)
	case "_completions":
		CommandCompletions(ts, state, query)
	default:
		CommandNext(ts, state, query)
	}
}
