def shrink(widths,term):
    w=widths[:]; total=sum(w)+2*(len(w)-1)
    while total>term:
        mi=max(range(len(w)),key=lambda i:(w[i],-i)) # first max? max key ties chooses larger -i = smaller i
        # Python max with key above returns first encountered max? (w, -i) smaller i favored
        w[mi]-=1; total-=1
    return w
for term in range(45,71): print(term,shrink([2,8,13,11,8,59],term))
