func dedupeYAMLNode(n *yaml.Node) {
	if n == nil {
		return
	}
	if n.Kind == yaml.MappingNode {
		seen := make(map[string]int)
		newContent := make([]*yaml.Node, 0, len(n.Content))
		for i := 0; i+1 < len(n.Content); i += 2 {
			keyNode := n.Content[i]
			valNode := n.Content[i+1]
			key := keyNode.Value
			if pos, ok := seen[key]; ok {
				newContent[pos] = keyNode
				newContent[pos+1] = valNode
			} else {
				seen[key] = len(newContent)
				newContent = append(newContent, keyNode, valNode)
			}
		}
		n.Content = newContent
	}
	for _, child := range n.Content {
		dedupeYAMLNode(child)
	}
	if n.Alias != nil {
		dedupeYAMLNode(n.Alias)
	}
}

func unmarshalYAML(data []byte, out interface{}) error {
	var node yaml.Node
	if err := yaml.Unmarshal(data, &node); err != nil {
		return err
	}
	if node.Kind == 0 {
		return nil
	}
	dedupeYAMLNode(&node)
