{"command":"cat > dstask/completions.go <<'EOF'
package dstask

import (
	"fmt"
	"os"
	"strings"
)

var completionOperatorCommands = map[string]bool{
	"next": true, "add": true, "remove": true, "log": true, "start": true,
	"stop": true, "done": true, "resolve": true, "context": true, "modify": true,
	"show-next": true, "show-projects": true, "show-active": true,
	"show-paused": true, "show-open": true, "show-resolved": true,
	"show-templates": true,
}

func parseForCompletion(args []string) (Query, string) {
	q := ParseQuery(args)
	explicit := ""
	noteMode := false
	for _, a := range args {
		if noteMode {
			continue
		}
		if a == "/" {
			noteMode = true
			continue
		}
		lower := strings.ToLower(a)
		if _, ok := commandAliases[lower]; ok {
			explicit = lower
			break
		}
	}
	if explicit == "" {
		q.Cmd = ""
	}
	return q, explicit
}

func hasCompletionOperators(q Query) bool {
	return len(q.Tags) > 0 || len(q.AntiTags) > 0 || q.Project != "" ||
		len(q.AntiProjects) > 0 || q.Priority != "" || q.Template != 0 || q.IgnoreContext
}

func CommandCompletions(ts *TaskSet, state State, q Query) {
	raw := []string{}
	if len(os.Args) > 2 {
		raw = os.Args[2:]
	}
	prefix := ""
	var simArgs []string
	if len(raw) > 1 {
		simArgs = raw[1:]
		prefix = raw[len(raw)-1]
	}
	cq, explicitCmd := parseForCompletion(simArgs)

	var candidates []string
	if explicitCmd == "help" {
		if hasCompletionOperators(cq) {
			return
		}
		candidates = append(candidates, completionCommands...)
	} else if explicitCmd == "" || completionOperatorCommands[explicitCmd] {
		if explicitCmd == "" && !hasCompletionOperators(cq) {
			candidates = append(candidates, completionCommands...)
		}
		candidates = append(candidates, "P0", "P1", "P2", "P3")
		for _, p := range ts.Projects() {
			candidates = append(candidates, "project:"+p.Name)
			candidates = append(candidates, "-project:"+p.Name)
		}
		var pool []*Task
		if explicitCmd == "context" || cq.IgnoreContext {
			pool = ts.FilterOpen()
		} else {
			pool = ts.FilterByQuery(ts.FilterOpen(), Query{}, state)
		}
		seenTags := make(map[string]bool)
		for _, t := range pool {
			for _, tag := range t.Tags {
				seenTags[tag] = true
			}
		}
		for tag := range seenTags {
			candidates = append(candidates, "+"+tag)
			candidates = append(candidates, "-"+tag)
		}
	} else {
		return
	}

	present := make(map[string]bool)
	for _, a := range simArgs {
		present[a] = true
	}
	for _, c := range candidates {
		if present[c] {
			continue
		}
		if strings.HasPrefix(c, prefix) {
			fmt.Println(c)
		}
	}
}
EOF
